krypton/settings.gradle.kts.text:
enableFeaturePreview("TYPESAFE_PROJECT_ACCESSORS")

dependencyResolutionManagement {
    repositories {
        mavenCentral()
        maven("https://repo.kryptonmc.org/releases")
        maven("https://oss.sonatype.org/content/groups/public/")
        maven("https://repo.kryptonmc.org/snapshots")
        maven("https://s01.oss.sonatype.org/content/repositories/snapshots/")
        maven("https://jitpack.io")
    }
    versionCatalogs {
        create("global") {
            from(files("gradle/global.versions.toml"))
        }
    }
}

pluginManagement {
    includeBuild("build-logic")
    repositories {
        maven("https://repo.spongepowered.org/repository/maven-public/")
        gradlePluginPortal()
    }
}

plugins {
    id("org.gradle.toolchains.foojay-resolver-convention") version "0.4.0"
}

rootProject.name = "krypton"

include("api")
include("server")
// Source archive contains generated API files; standalone developer generator excluded from server packaging.
include("annotation-processor")
include("jar")

internalProject("annotations")
internalProject("ap")

pluginProject("bans")
pluginProject("whitelist")

fun internalProject(name: String) {
    include("internal-$name")
    project(":internal-$name").projectDir = file("internal/$name")
}

fun pluginProject(name: String) {
    include("$name-plugin")
    project(":$name-plugin").projectDir = file("plugins/$name")
}

// BEGIN VOLTRA PINNED PUBLISHER SOURCE COMPOSITE
includeBuild("../nbt-src") {
    dependencySubstitution {
        substitute(module("org.kryptonmc:nbt-common")).using(project(":common"))
        substitute(module("org.kryptonmc:nbt-extra-kotlin")).using(project(":extra-kotlin"))
    }
}
includeBuild("../serialization-src") {
    dependencySubstitution {
        substitute(module("org.kryptonmc:serialization-core")).using(project(":serialization-core"))
        substitute(module("org.kryptonmc:serialization-gson")).using(project(":serialization-gson"))
        substitute(module("org.kryptonmc:serialization-nbt")).using(project(":serialization-nbt"))
    }
}
includeBuild("../brigadier-src") {
    dependencySubstitution {
        substitute(module("org.kryptonmc:krypton-brigadier")).using(project(":"))
    }
}
includeBuild("../DataConverter-src") {
    dependencySubstitution {
        substitute(module("ca.spottedleaf:dataconverter")).using(project(":"))
    }
}

krypton/server/build.gradle.kts.text:
import org.apache.tools.ant.filters.ReplaceTokens

plugins {
    id("krypton.api-conventions")
    id("io.gitlab.arturbosch.detekt")
    id("com.google.devtools.ksp")
    jacoco
}

dependencies {
    api(projects.api)
    implementation(projects.annotationProcessor)

    // Logging and console
    runtimeOnly(libs.log4j.core)
    implementation(libs.tca)
    runtimeOnly(libs.jline.jansi)

    // Data
    api(libs.dataConverter)
    api(libs.nbt)
    api(libs.nbt.kotlin)
    api(libs.serialization)
    api(libs.serialization.gson)
    api(libs.serialization.nbt)
    implementation(files(rootProject.file("../articdata-data.jar"))) // Explicit same-Minecraft publisher-data restoration; original artifact unavailable.

    // Collections and caching
    implementation(libs.fastutil)
    implementation(libs.flare.fastutil)
    implementation(libs.caffeine)
    implementation(libs.jctools)

    // Miscellaneous
    implementation(libs.clikt)
    implementation(libs.bstats)
    implementation(libs.kotlinx.collections.immutable)
    compileOnly(projects.internalAnnotations)
    ksp(projects.internalAp)
    implementation(libs.reflections)
    implementation(libs.hydrazine)

    testImplementation(libs.junit.api)
    testImplementation(libs.junit.engine)
    testImplementation(libs.kotlin.test.junit)
    testImplementation(libs.junit.platform.runner)
    testImplementation(libs.mockk)
    testImplementation(libs.jimfs)
    testRuntimeOnly(libs.bytebuddy)
    testImplementation(projects.internalAnnotations)
    testImplementation(libs.equalsVerifier)
    testImplementation(libs.jsonassert)
}

license {
    exclude(
        "**/*.properties",
        "**/*.conf",
        "**/*.json",
        // Velocity derivatives, with a special header
        "**/plugin/KryptonPluginManager.kt",
        "**/plugin/PluginClassLoader.kt",
        "**/plugin/PluginDependencies.kt",
        // Sponge derivatives, with a special header
        "**/console/BrigadierCompleter.kt",
        "**/console/BrigadierHighlighter.kt"
    )
}

tasks {
    withType<ProcessResources> {
        filesMatching("**/versions.properties") {
            val minecraftVersion = global.versions.minecraft.get()
            filter<ReplaceTokens>("tokens" to mapOf(
                "krypton" to project.version.toString(),
                "minecraft" to minecraftVersion,
                "data" to minecraftVersion.replace('.', '_')
            ))
        }
    }
    jacocoTestReport {
        dependsOn(test)
        reports {
            html.required.set(true)
            xml.required.set(true)
        }
    }
    build {
        dependsOn(test)
    }
    compileKotlin {
        compilerOptions.freeCompilerArgs.add("-Xjvm-default=all")
    }
    withType<Test> {
        useJUnitPlatform()
    }
}

setupDetekt()

brigadier-src/build.gradle.text:
apply plugin: 'java-library'
apply plugin: 'maven-publish'

group = 'org.kryptonmc'
version = project.hasProperty('buildNumber') ? "${project.majorMinor}.${project.buildNumber}" : "${project.majorMinor}.0-SNAPSHOT"

buildscript {
    repositories {
        mavenCentral()
        maven {
            url "https://libraries.minecraft.net"
        }
    }
}

repositories {
    maven {
        url "https://libraries.minecraft.net"
    }
    mavenCentral()
}

dependencies {
    testImplementation 'com.google.guava:guava:26.0-jre'
    testImplementation 'junit:junit-dep:4.11'
    testImplementation 'org.hamcrest:hamcrest-library:1.3'
    testImplementation 'org.mockito:mockito-core:1.10.19'
    testImplementation 'com.google.guava:guava-testlib:26.0-jre'
    testImplementation 'org.openjdk.jmh:jmh-core:1.21'
    annotationProcessor 'org.openjdk.jmh:jmh-generator-annprocess:1.21'
}

task sourcesJar(type: Jar) {
    archiveClassifier.set('sources')
    from sourceSets.main.allSource
}

sourceSets {
    main {
        java {
            srcDirs = ['src/main/java']
        }
        resources {
            srcDirs = ['src/main/resources']
        }
    }
    test {
        java {
            srcDirs = ['src/test/java']
        }
        resources {
            srcDirs = ['src/test/resources']
        }
    }
}

artifacts {
    archives jar
    archives sourcesJar
}

test {
    testLogging {
        events "failed", "skipped"
        showStandardStreams = true
        showExceptions true
    }
}

publishing {
    publications {
        mavenJava(MavenPublication) {
            from components.java
            artifact sourcesJar
        }
    }
}

task report {
    doLast {
        println "##teamcity[buildNumber '${project.version}']"
    }
}

publishing {
    repositories {
        maven {
            credentials {
                username System.getenv("NEXUS_USERNAME")
                password System.getenv("NEXUS_PASSWORD")
            }

            name = 'krypton'
            def base = 'https://repo.kryptonmc.org'
            def releasesRepoUrl = "$base/releases"
            def snapshotsRepoUrl = "$base/snapshots"
            url = version.endsWith('SNAPSHOT') ? snapshotsRepoUrl : releasesRepoUrl
        }
    }
}

